from pathlib import Path
p=Path('review/INVESTMENT_COMMITTEE_REVIEW.md');s=p.read_text(encoding='utf-8-sig').replace('64-file','67-file').replace('A $100,000 replica could have shown about $36,150 peak-to-trough loss in this retrospective replay.','A portfolio worth $100,000 at its peak would have fallen about $36,151 in this retrospective replay.').replace('at most 2% per stock and 5% per sector in that sleeve','at most 2% of total capital per directly held stock and 5% of total capital per sector in that direct-stock sleeve').replace('Count all existing accounts and fund look-through holdings.','Separately report aggregate issuer and sector exposure including fund look-through holdings and all existing accounts; these proposed direct-stock caps are not a claim that an index fund meets the same issuer limits.').replace('so the first weekly report can convert this research into portfolio-specific buy/hold/reduce/sell decisions.','so the first weekly report can assess actual exposures and determine which actions are applicable; any new buy still must clear the evidence gates.')
